  'privacy.eyebrow': 'página estática',
  'privacy.title': 'Qué guardamos',
  'privacy.item1': 'Solo guardamos lo que la app necesita: tu nombre, e-mail, contraseña (cifrada con hash — nunca la vemos en texto plano), tus valoraciones y reseñas, y tu historial de escucha si conectaste Spotify o lo subiste tú.',
  'privacy.item2': 'No pedimos ni guardamos tu edad, ciudad o teléfono — nada de eso hace falta para comparar gustos musicales.',
  'privacy.item3': 'Tu perfil completo (estadísticas, historial de valoraciones) solo lo ven tú y tus amigos, o todos si lo abres en ajustes. Cualquiera puede encontrarte por nombre, pero solo un amigo puede abrir tu perfil mientras esté cerrado.',
  'privacy.item4': 'Las portadas y los datos de las canciones vienen directamente de Spotify y Deezer — no guardamos ni distribuimos archivos de música.',
  'privacy.item5': 'Puedes borrar tu cuenta cuando quieras desde ajustes — eso elimina todo lo anterior sin posibilidad de recuperarlo.',
