  'privacy.title': 'Was wir speichern',
  'privacy.item1': 'Wir speichern nur, was die App braucht: deinen Namen, deine E-Mail, dein Passwort (gehasht — wir sehen es nie im Klartext), deine Bewertungen und Rezensionen und deinen Hörverlauf, falls du Spotify verbunden oder ihn selbst hochgeladen hast.',
  'privacy.item2': 'Wir fragen weder nach Alter, Wohnort noch Telefonnummer und speichern sie nicht — für den Musikgeschmack-Vergleich braucht es nichts davon.',
  'privacy.item3': 'Dein vollständiges Profil (Statistiken, Bewertungsverlauf) sehen nur du und deine Freunde, oder alle, wenn du es in den Einstellungen öffnest. Jeder kann dich über den Namen finden, aber nur Freunde können dein geschlossenes Profil öffnen.',
  'privacy.item4': 'Cover und Titeldaten kommen direkt von Spotify und Deezer — wir speichern oder verbreiten keine Musikdateien.',
  'privacy.item5': 'Du kannst dein Konto jederzeit in den Einstellungen löschen — das entfernt alles oben Genannte unwiderruflich.',
